def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    # Endgame: exploit hard in final rounds, but avoid provoking earlier.
    if n >= 97:
        return 'D'
    if n == 96:
        # last chance to be nice if they're cooperative
        if history[-1][1] == 'C':
            return 'C'
        return 'D'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    def count(seq, ch):
        c = 0
        for x in seq:
            if x == ch:
                c += 1
        return c

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    opp_d = count(opp, 'D')
    opp_c = n - opp_d
    my_d = count(own, 'D')
    last_opp = opp[-1]
    last_own = own[-1]

    # Detect repeated defection bursts
    opp_d_streak = streak(opp, 'D')
    my_d_streak = streak(own, 'D')

    # Recent window for behavior rate
    w = 12 if n >= 12 else n
    recent_d = count(opp[-w:], 'D')

    # Strong, bounded retaliation against sustained defection.
    if opp_d_streak >= 3:
        return 'D'
    if opp_d_streak == 2:
        # Punish but consider one conciliatory move if overall they were fine.
        if opp_d <= 2 and n > 6:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Single defection: retaliate once, then be ready to forgive.
    if last_opp == 'D':
        if last_own == 'D':
            # We already punished; try to restore cooperation.
            if opp_d <= 2 or (recent_d <= 2):
                return 'C'
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    opp_rate = opp_d / float(n)
    recent_rate = recent_d / float(w)

    # Mostly cooperative opponent: preserve mutual cooperation.
    if recent_rate <= 0.25 and opp_rate <= 0.3:
        # Rare exploitation, mostly near end but not too early.
        if n > 15 and n < 90:
            if my_d_streak == 0 and rng.random() < 0.05:
                return 'D'
        return 'C'

    # Moderately defective: cooperate but punish more readily.
    if recent_rate <= 0.5 and opp_rate <= 0.5:
        # Avoid being exploited repeatedly: if we're being taken advantage of,
        # defect a bit more.
        if opp_d > opp_c and n > 10:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Hostile opponent: defect mostly, probe rarely.
    if last_opp == 'D':
        return 'D'
    if rng.random() < 0.15:
        return 'C'
    return 'D'
